<details>
<summary>Program.cs</summary>

```csharp
// Headless repro: drives Microsoft.AspNetCore.Components.WebView's IPC through a minimal WebViewManager, with this
// program playing the role of the browser (blazor.webview.js). No WebView2 / UI involved.
using System.Collections.Concurrent;
using System.Text.Json;
using BlazorWebViewAotRepro;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Web;
using Microsoft.AspNetCore.Components.WebView;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.FileProviders;
using Microsoft.Extensions.Logging;

var aot = System.Runtime.JitInfo.GetCompiledMethodCount() == 0;
Console.WriteLine($"NativeAOT: {aot}, JsonSerializer.IsReflectionEnabledByDefault: {JsonSerializer.IsReflectionEnabledByDefault}");

var services = new ServiceCollection()
    .AddLogging(b => b.AddProvider(new CapturingLoggerProvider()).SetMinimumLevel(LogLevel.Error))
    .AddBlazorWebView()
    .BuildServiceProvider();

var dispatcher = new RecordingDispatcher(Dispatcher.CreateDefault());
var manager = new HeadlessWebViewManager(services, dispatcher);
await manager.AddRootComponentAsync(typeof(Probe), "#app", ParameterView.Empty);
manager.Navigate("/");

var results = new List<(string Step, bool Ok, string Detail)>();

async Task Step(string name, Func<Task> action, Func<bool> succeeded)
{
    dispatcher.Errors.Clear();
    Probe.JSInteropError = null;
    try
    {
        await action();
        await Task.Delay(500);
    }
    catch (Exception ex)
    {
        dispatcher.Errors.Enqueue(ex);
    }

    var error = dispatcher.Errors.FirstOrDefault() ?? Probe.JSInteropError ?? CapturingLoggerProvider.Errors.FirstOrDefault();
    CapturingLoggerProvider.Errors.Clear();
    var ok = succeeded() && error is null;
    results.Add((name, ok, error is null ? "" : $"{error.GetType().Name}: {FirstLine(error.Message)}"));
}

// 1. JS -> .NET: AttachPage (IpcCommon.TryDeserialize -> JsonElement[]). Success = .NET replies with AttachToDocument.
await Step("Receive AttachPage (deserialize JsonElement[])",
    () => { manager.ReceiveFromJs("AttachPage", "https://0.0.0.1/", "https://0.0.0.1/"); return Task.CompletedTask; },
    () => manager.Sent.Any(m => m.Type == "AttachToDocument"));

// 2. .NET -> JS: AttachToDocument / RenderBatch (IpcCommon.Serialize -> IEnumerable<object> of int/long/string).
await Step("Send AttachToDocument + RenderBatch (serialize int/long/string)",
    () => Task.CompletedTask,
    () => manager.Sent.Any(m => m.Type == "RenderBatch"));

// 3. .NET -> JS: BeginInvokeJS (enum arguments JSCallResultType / JSCallType). Triggered by OnAfterRender, which runs
//    once the "browser" acknowledges the first render batch.
await Step("Send BeginInvokeJS (serialize enums)",
    () =>
    {
        var batch = manager.Sent.First(m => m.Type == "RenderBatch");
        manager.ReceiveFromJs("OnRenderCompleted", batch.Args[0].GetInt64(), null);
        return Task.CompletedTask;
    },
    () => manager.Sent.Any(m => m.Type == "BeginInvokeJS"));

// 4. .NET -> JS: Navigate (NavigationOptions struct argument).
await Step("Send Navigate (serialize NavigationOptions struct)",
    () => manager.TryDispatchAsync(sp => sp.GetRequiredService<NavigationManager>().NavigateTo("/next")),
    () => manager.Sent.Any(m => m.Type == "Navigate"));

Console.WriteLine();
foreach (var (step, ok, detail) in results)
{
    Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {step}{(ok ? "" : "\n      " + detail)}");
}

return results.All(r => r.Ok) ? 0 : 1;

static string FirstLine(string s) => s.Split('\n')[0].Trim();

namespace BlazorWebViewAotRepro
{
    internal sealed class HeadlessWebViewManager(IServiceProvider services, Dispatcher dispatcher)
        : WebViewManager(services, dispatcher, new Uri("https://0.0.0.1/"), new NullFileProvider(), new JSComponentConfigurationStore(), "index.html")
    {
        private const string Prefix = "__bwv:";
        private static readonly Uri Origin = new("https://0.0.0.1/");

        public ConcurrentQueue<(string Type, JsonElement[] Args)> Sent { get; } = new();

        protected override void NavigateCore(Uri absoluteUri)
        {
        }

        // .NET -> "browser". Parsed with JsonDocument, which is AOT safe, so failures can only come from Blazor.
        protected override void SendMessage(string message)
        {
            using var doc = JsonDocument.Parse(message.AsMemory(Prefix.Length));
            var items = doc.RootElement.EnumerateArray().Select(e => e.Clone()).ToArray();
            Sent.Enqueue((items[0].GetString()!, items[1..]));
        }

        // "Browser" -> .NET, in the same wire format as blazor.webview.js.
        public void ReceiveFromJs(string messageType, params object?[] args)
        {
            using var buffer = new MemoryStream();
            using (var writer = new Utf8JsonWriter(buffer))
            {
                writer.WriteStartArray();
                writer.WriteStringValue(messageType);
                foreach (var arg in args)
                {
                    switch (arg)
                    {
                        case null: writer.WriteNullValue(); break;
                        case string s: writer.WriteStringValue(s); break;
                        case long l: writer.WriteNumberValue(l); break;
                        default: throw new NotSupportedException(arg.GetType().Name);
                    }
                }
                writer.WriteEndArray();
            }

            MessageReceived(Origin, Prefix + System.Text.Encoding.UTF8.GetString(buffer.ToArray()));
        }
    }

    // Captures exceptions that Blazor catches and only logs (e.g. WebViewNavigationManager on a failed navigation).
    internal sealed class CapturingLoggerProvider : ILoggerProvider, ILogger
    {
        public static ConcurrentQueue<Exception> Errors { get; } = new();

        public ILogger CreateLogger(string categoryName) => this;

        public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;

        public bool IsEnabled(LogLevel logLevel) => logLevel >= LogLevel.Error;

        public void Log<TState>(LogLevel logLevel, EventId eventId, TState state, Exception? exception, Func<TState, Exception?, string> formatter)
        {
            if (exception is not null)
            {
                Errors.Enqueue(exception);
            }
        }

        public void Dispose()
        {
        }
    }

    // Records exceptions from work items (WebViewManager.MessageReceived and IpcSender report failures through
    // fire-and-forget dispatcher tasks, so they would otherwise go unobserved).
    internal sealed class RecordingDispatcher(Dispatcher inner) : Dispatcher
    {
        public ConcurrentQueue<Exception> Errors { get; } = new();

        public override bool CheckAccess() => inner.CheckAccess();

        public override Task InvokeAsync(Action workItem) => Record(inner.InvokeAsync(workItem));

        public override Task InvokeAsync(Func<Task> workItem) => Record(inner.InvokeAsync(workItem));

        public override Task<TResult> InvokeAsync<TResult>(Func<TResult> workItem) => Record(inner.InvokeAsync(workItem));

        public override Task<TResult> InvokeAsync<TResult>(Func<Task<TResult>> workItem) => Record(inner.InvokeAsync(workItem));

        private T Record<T>(T task) where T : Task
        {
            task.ContinueWith(t => Errors.Enqueue(t.Exception!.GetBaseException()), TaskContinuationOptions.OnlyOnFaulted);
            return task;
        }
    }
}
```
</details>

### Proposed fix

All changes are internal to `Microsoft.AspNetCore.Components.WebView`, except that `[DynamicallyAccessedMembers]` is
added to one public parameter. The IPC wire format stays the same.

1. **Source-generated JSON for IPC.** Add an internal `JsonSerializerContext` covering `JsonElement[]` and the closed set of outgoing argument types: `string`, `bool`, `int`, `long`, `byte[]`, `JSCallResultType`, `JSCallType` and `NavigationOptions`. Use camelCase naming to match `JsonSerializerOptionsProvider`.
   - `TryDeserialize` uses the generated `JsonTypeInfo<JsonElement[]>`, and parses the message type with
     `Enum.Parse<TEnum>`.
   - `Serialize` writes the array with a `Utf8JsonWriter`: first the message type, then each argument through the
     context (`null` written as JSON null). An argument type the context doesn't cover throws a clear exception, so new message types can't silently regress AOT.
2. **Annotate the root component type flow** with `[DynamicallyAccessedMembers(LinkerFlags.Component)]`: `WebViewManager.AddRootComponentAsync`'s `componentType`, `RootComponent.ComponentType` and `WebViewRenderer.AddRootComponent(Type, string)`. `WebRenderer.AddRootComponent` already requires it.
3. **Replace `Assembly.Location`** in `StaticWebAssetsLoader` with `AppContext.BaseDirectory` and the entry assembly's name.
4. **Mark the project trim/AOT compatible** (`IsTrimmable` / `IsAotCompatible`), so the analyzers keep it that way and `TrimMode=partial` trims it.

## Background and Motivation

Microsoft.AspNetCore.Components (issue #50260; implementation in the attached fix file) resolves an accidental coupling that caused server-side-rendered (SSR) component scopes to select their NavigationManager implementation based on whether the app is configured for interactive server components. That coupling made SSR resolution depend on an unrelated configuration (AddServerComponents/AddServerSideBlazor), leading to inconsistent behavior between SSR-only and interactive applications.

Today:
- If an app does not call AddServerComponents(), SSR component scopes resolve NavigationManager to HttpNavigationManager.
- If an app does call AddServerComponents(), both SSR and interactive server component scopes resolve NavigationManager to RemoteNavigationManager.

Expected:
- SSR scopes should always use HttpNavigationManager.
- Interactive/server circuit scopes should use RemoteNavigationManager.

Motivation:
- The current behavior can produce subtle runtime differences because HttpNavigationManager and RemoteNavigationManager have different semantics and side effects. The issue author observed this causing tests to be misleading (bug #49670), where E2E tests passed only for apps that registered interactive server components. Making DI resolution deterministic by scope reduces the risk of regressions and ensures identical behavior for SSR-produced content regardless of unrelated configuration.

What this change does:
- Adds an internal HasCircuitContext flag on ICircuitAccessor and sets it for circuit scopes.
- Registers both the interactive (Remote*) and non-interactive (Http/Unsupported*) concrete implementations in DI and uses scope-aware factories to resolve service abstractions (NavigationManager, IJSRuntime, INavigationInterception, IScrollToLocationHash).
- Adds tests that validate preservation of an existing NavigationManager outside circuit scopes and selection of RemoteNavigationManager inside circuit scopes.

No public API changes:
- This proposal does not introduce public or protected API surface changes; the modifications are implementation-level and affect DI registration and resolution behavior only.


## Usage Examples

The implementation includes tests demonstrating the intended consumer-visible behavior.

- Preserve existing (non-interactive) NavigationManager outside of a circuit scope:

```csharp
var services = new ServiceCollection();
services.AddLogging();
services.AddScoped<NavigationManager, TestNavigationManager>();
services.AddServerSideBlazor();

using var scope = services.BuildServiceProvider().CreateScope();
var navigationManager = scope.ServiceProvider.GetRequiredService<NavigationManager>();

// Assert: preserves the TestNavigationManager outside circuit scopes
Assert.IsType<TestNavigationManager>(navigationManager);
```

- Use RemoteNavigationManager inside a circuit scope:

```csharp
((DefaultCircuitAccessor)scope.ServiceProvider.GetRequiredService<ICircuitAccessor>()).HasCircuitContext = true;
var navigationManager = scope.ServiceProvider.GetRequiredService<NavigationManager>();

// Assert: uses RemoteNavigationManager inside circuit scopes
Assert.IsType<RemoteNavigationManager>(navigationManager);
```


## Proposed API

Summary: There are no public or protected API surface changes in this implementation. The change is internal and limited to DI behavior to ensure SSR scopes and interactive/server scopes select the proper service implementations.

For reviewer clarity, internal ref-like excerpts are shown below (implementation evidence):

```diff
namespace Microsoft.AspNetCore.Components.Server.Circuits
{
-    internal interface ICircuitAccessor
-    {
-        Circuit Circuit { get; }
-    }
+    internal interface ICircuitAccessor
+    {
+        Circuit Circuit { get; }
+        bool HasCircuitContext { get; }
+    }

-    internal sealed class DefaultCircuitAccessor : ICircuitAccessor
-    {
-        public Circuit Circuit { get; set; }
-    }
+    internal sealed class DefaultCircuitAccessor : ICircuitAccessor
+    {
+        public Circuit Circuit { get; set; }
+        public bool HasCircuitContext { get; set; }
+    }
}
```

Implementation notes (non-public):

- Component DI registration logic was changed so AddServerSideBlazor() and AddRazorComponents() register both the interactive (Remote*) and non-interactive (Http/Unsupported*) types, and then resolve NavigationManager/IJSRuntime/INavigationInterception/IScrollToLocationHash by checking whether the current scope has circuit context.

- Example from the implementation: in AddServerSideBlazor, whereas previously the code registered:

```csharp
services.AddScoped<NavigationManager, RemoteNavigationManager>();
services.AddScoped<IJSRuntime, RemoteJSRuntime>();
```

now the code registers concrete types and uses factories that check `ICircuitAccessor.HasCircuitContext` to decide which implementation to resolve.


## Alternative Designs

N/A — there are no alternative designs documented for this change.


## Risks

Documented risks based on the originating issue and the nature of the change:

- Behavioral divergence between implementations:
  - "This shouldn't currently impact the developer experience or behavior. However it might do, since the two implementations are quite different, and might vary behavior." — originating issue.
  - Some apps that relied (accidentally) on the previous selection behavior may observe a change in behavior. Reviewers should validate scenarios where application code depends on NavigationManager or related services.

- Test and compatibility risk:
  - The issue notes this was the root cause of bug #49670: E2E tests could pass only for apps that had `AddServerComponents()`.
  - Recommendation: verify functional tests and E2E tests that exercise navigation and JS runtime behavior to ensure correctness for both SSR-only and interactive apps.

- Observable DI-behavior change:
  - The change adds an internal `HasCircuitContext` flag on `ICircuitAccessor` used to control resolution. While internal, this is an observable runtime selection change and should be validated across scenarios.


## Source justification

The following claims map to the originating issue and the provided implementation fix file.

- Problem statement and expected behavior:

  "SSR components currently select between the two implementations based on an entirely unrelated fact (whether or not your app is configured to support interactive server components), which is problematic." — originating issue.

  "Regardless of service registrations, the DI scope for SSR components should use `HttpNavigationManager` while the DI scope for interactive (server) components should use `RemoteNavigationManager`." — originating issue.

- Implementation evidence (see provided fix file):
  - DI registration changes in AddRazorComponents (Components.Endpoints): replaced registrations like `services.TryAddScoped<NavigationManager, HttpNavigationManager>()` with explicit concrete registrations and factory-based resolution. (See implementation in the attached fix file.)

  - In AddServerSideBlazor (Components.Server), DI selection now checks `ICircuitAccessor.HasCircuitContext` to decide between `RemoteNavigationManager` and the existing registrations. (See implementation in the attached fix file.)

  - `ICircuitAccessor` and `DefaultCircuitAccessor` were extended with a `HasCircuitContext` property. The circuit factory sets `HasCircuitContext = true` for circuit scopes. (See implementation in the attached fix file.)


## Checklist of inputs used

